[CmdletBinding()]
param([Parameter(Mandatory)][string[]]$EvidenceDirectories,[switch]$SingleRun,[switch]$ComponentDiagnostic,[string]$ReportPath,[string]$SourceDirectory=$PSScriptRoot)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
function Require([bool]$Value,[string]$Reason){if(-not $Value){throw $Reason}}
function Json([string]$Path){Get-Content -LiteralPath $Path -Raw | ConvertFrom-Json -AsHashtable}
function SafePath([string]$Root,[string]$Relative){$r=[IO.Path]::GetFullPath($Root);$p=[IO.Path]::GetFullPath((Join-Path $r $Relative));Require ($p.StartsWith($r+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)) 'Evidence path escapes root';return $p}
function Wire([string]$Text){
    $stream=[IO.MemoryStream]::new([Convert]::FromBase64String($Text),$false);$reader=[IO.BinaryReader]::new($stream)
    try{Require ([Net.IPAddress]::NetworkToHostOrder($reader.ReadInt32()) -eq 0x58524631) 'Wire version';$count=[Net.IPAddress]::NetworkToHostOrder($reader.ReadInt32());Require ($count -ge 0 -and $count -le 96) 'Wire count';$result=[ordered]@{};$previous=''
        for($i=0;$i -lt $count;$i++){$pair=@();for($j=0;$j -lt 2;$j++){$length=[Net.IPAddress]::NetworkToHostOrder($reader.ReadInt32());Require ($length -ge 0 -and $length -le 524288) 'Wire field size';$bytes=$reader.ReadBytes($length);Require ($bytes.Length -eq $length) 'Truncated wire';$utf=[Text.UTF8Encoding]::new($false,$true);$pair+=$utf.GetString($bytes)};Require ([StringComparer]::Ordinal.Compare($pair[0],$previous) -gt 0) 'Duplicate/noncanonical fields';$previous=$pair[0];$result[$pair[0]]=$pair[1]};Require ($stream.Position -eq $stream.Length) 'Trailing wire bytes';return $result
    }finally{$reader.Dispose();$stream.Dispose()}
}
function Rows($Value){@($Value | Where-Object {$null -ne $_})}
function Key($Row){return $Row.fixture_id+'|'+$Row.tenant_id+'|'+$Row.operation_id}
$ApprovedSources=@('README.md','Invoke-CrossControlIntegrationProbe.ps1','Verify-CrossControlIntegrationEvidence.ps1','scenarios.json','fixtures/identity-authority.sql','fixtures/placement-authority.sql','fixtures/operations-authority.sql','fixtures/recovery-authority.sql','fixtures/workload.sql','fixtures/recovery-gate.sql')+@('LabIntegrationTrust','LabIdentityAuthority','LabPlacementAuthority','LabOperationsAuthority','LabRecoveryAuthority','LabIntegrationRouter','LabOwningWorkload','OwnerOperationStore','ReconciliationPolicy','RecoveryCoordinator','BackupRestore','ScenarioBarriers','StateEffectEvidence','CrossControlIntegrationProbe' | ForEach-Object {"src/test/java/ir/neshane/isolationprobe/integration/$_.java"})
function WireBytes($Value){
    $stream=[IO.MemoryStream]::new();$writer=[IO.BinaryWriter]::new($stream)
    try{$writer.Write([Net.IPAddress]::HostToNetworkOrder([int]0x58524631));$writer.Write([Net.IPAddress]::HostToNetworkOrder([int]$Value.Count));[string[]]$keys=@($Value.Keys);[Array]::Sort($keys,[StringComparer]::Ordinal);foreach($key in $keys){foreach($text in @($key,[string]$Value[$key])){$bytes=[Text.Encoding]::UTF8.GetBytes($text);$writer.Write([Net.IPAddress]::HostToNetworkOrder([int]$bytes.Length));$writer.Write($bytes)}};$writer.Flush();return ,$stream.ToArray()}finally{$writer.Dispose();$stream.Dispose()}
}
function Digest($Value){return [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData((WireBytes $Value))).ToLowerInvariant()}
function Signed([string]$Root,[string]$Certificate,[string]$Body,[string]$Signature){
    Require ($Certificate -match '^[a-z-]+\.cer$') 'Public certificate name invalid';$cert=[Security.Cryptography.X509Certificates.X509Certificate2]::new([IO.File]::ReadAllBytes((SafePath $Root ('public-certificates/'+$Certificate))))
    try{$key=[Security.Cryptography.X509Certificates.ECDsaCertificateExtensions]::GetECDsaPublicKey($cert);Require ($null -ne $key) 'ECDSA public key required';try{Require ($key.VerifyData([Convert]::FromBase64String($Body),[Convert]::FromBase64String($Signature),[Security.Cryptography.HashAlgorithmName]::SHA256,[Security.Cryptography.DSASignatureFormat]::Rfc3279DerSequence)) 'Independent signature verification failed'}finally{$key.Dispose()}}finally{$cert.Dispose()}
}
function FenceFrontier([string]$Root,$Snapshot,[string]$Fixture,[string]$Tenant,[string]$Vector){
    $expected=Wire $Vector;$maximum=[long]0
    foreach($domain in @('identity','placement','operations','recovery')){
        $rows=@($Snapshot.authorities[$domain].documents | Where-Object tenant_id -eq $Tenant);Require ($rows.Count -eq 1) 'Completion frontier lacks scoped authority state';$state=Wire $rows[0].body;Require ($state.fixture -eq $Fixture -and $state.tenant -eq $Tenant -and $state.phase -eq 'COMPLETE' -and $expected[$domain+'-authority'] -eq ($state.revision+'|'+$state.incarnation)) 'Completion frontier authority vector/scope mismatch'
        if(-not $state.Contains('acks')){continue};$acks=Wire $state.acks;Require ($acks.Count -eq 3) 'Completion frontier missing owning-service fence ACKs'
        foreach($peer in @('owner-a','owner-b','owner-c')){
            $envelope=Wire $acks[$peer];Signed $Root ($peer+'.cer') $envelope.body $envelope.signature;$ack=Wire $envelope.body;$intent=Wire $ack.intent;$persisted=@($Snapshot.owners[$peer.Substring(6)].fenceAcknowledgements | Where-Object transition_id -eq $state.transition)
            Require ($ack.owner -eq $peer -and $ack.fixture -eq $Fixture -and $ack.tenant -eq $Tenant -and $ack.transition -eq $state.transition -and $intent.issuer -eq ($domain+'-authority') -and $intent.fixture -eq $Fixture -and $intent.tenant -eq $Tenant -and $intent.owner -eq $peer -and $intent.transition -eq $state.transition) 'Completion frontier ACK/intent scope invalid'
            $frontier=[long]$ack.'completion-frontier';$pending=[long]$ack.'pending-completions';Require ($frontier -ge 0 -and $pending -ge 0 -and $pending -le $frontier -and $persisted.Count -eq 1 -and [long]$persisted[0].completion_frontier -eq $frontier -and [long]$persisted[0].pending_completions -eq $pending -and $persisted[0].revision_vector -eq $ack.intent) 'Signed frontier not bound to durable ACK metadata';$maximum=[Math]::Max($maximum,$frontier)
        }
    }
    $placement=Wire (@($Snapshot.authorities.placement.documents | Where-Object tenant_id -eq $Tenant)[0].body);Require ($placement.source -in @('cell-a','cell-b','cell-c')) 'Recovery frontier lacks fenced source placement';$sourceOps=@($Snapshot.owners[$placement.source.Substring(5)].operations | Where-Object tenant_id -eq $Tenant);$sourceMaximum=if($sourceOps.Count){[long]($sourceOps | Measure-Object sequence -Maximum).Maximum}else{[long]0};Require ($maximum -ge $sourceMaximum) 'Signed fence frontier is behind independently observed source commits';return $maximum
}
