    $certs=Json "$e/public-certificate-hashes.json";Require ($certs.Count -eq 19) 'Public certificate inventory mismatch';foreach($name in $certs.Keys){Require ((Get-FileHash (SafePath $e ('public-certificates/'+$name))).Hash -eq $certs[$name]) 'Public certificate pin mismatch'}
    $sources=Json "$e/sources.json";Require ($sources.Count -eq 24) 'Diagnostic source inventory mismatch';foreach($name in $sources.Keys){Require ((Get-FileHash (SafePath $SourceDirectory $name)).Hash -eq $sources[$name]) "Executed source changed $name"}
    Require (@(Compare-Object @($ApprovedSources | Sort-Object) @($sources.Keys | Sort-Object)).Count -eq 0) 'Exact 24-file allowlist mismatch'
    Require ((Get-FileHash "$e/scenarios.json").Hash -eq 'FE00683665213BA09630604677787F7CE88D95F78AD57D91ECC08E6E69363B23' -and $sources['scenarios.json'] -eq 'FE00683665213BA09630604677787F7CE88D95F78AD57D91ECC08E6E69363B23') 'Approved frozen matrix changed'
    $ceremonies=@(Get-Content "$e/anchor-ceremonies.jsonl" | ForEach-Object {$_ | ConvertFrom-Json -AsHashtable});$proofs=0
