    $diagnosticIds+=@('X02-a','X04-a','X02-b','X04-b')
    $diagnosticIds+=@('X11-a','X12-a','X11-b','X12-b')
    $diagnosticIds+=@('X13-a','X34-a','X13-b','X34-b')
    $diagnosticIds+=@('X15-a','X15-b','X22-a','X22-b','X25-a','X25-b')
    $diagnosticIds+=@('X14-a','X14-b')
    foreach($scenario in @('X16','X17','X18','X19')){foreach($variant in @('a','b')){$diagnosticIds+=$scenario+'-'+$variant}}
    foreach($scenario in @('X20','X24')){foreach($variant in @('a','b')){$diagnosticIds+=$scenario+'-'+$variant}}
    foreach($scenario in @('X21','X23')){foreach($variant in @('a','b')){$diagnosticIds+=$scenario+'-'+$variant}}
    foreach($id in $diagnosticIds){
        $before=Json "$e/state-$id-before.json";$after=Json "$e/state-$id-after.json";$tenant='tenant-'+$id.Substring(4);$isLostAck=$id.StartsWith('X39');$isActivationRace=$id.StartsWith('X33');$isRecovery=$id.StartsWith('X38') -or $isLostAck -or $isActivationRace;$isRevocation=$id.StartsWith('X06');$isInterruption=$id.StartsWith('X35');$isAuthorityNegative=$id.StartsWith('X26') -or $id.StartsWith('X27');$isRestart=$id.StartsWith('X28');$isPartial=$id.StartsWith('X29');$isDelayed=$id.StartsWith('X30');$isSecurityRace=$id.StartsWith('X31') -or $id.StartsWith('X32');$isCombined=$id.StartsWith('X32');Require ($before.observer.readOnly -and $after.observer.readOnly -and $before.observer.databases.Count -eq 7 -and $after.observer.databases.Count -eq 7 -and $before.witnessDigest -eq $after.witnessDigest) 'Diagnostic SQL/witness observation failed'
