            $scopeTenant=if($cell -eq 'c'){$tenant}else{'tenant-'+$cell};Require (@($owner.gate).Count -eq 1 -and $owner.gate[0].fixture_id -eq $id -and $owner.gate[0].tenant_id -eq $scopeTenant -and $owner.gate[0].cell_id -eq ('cell-'+$cell) -and $owner.gate[0].deployment_id -eq ('deployment-'+$cell)) 'Owner database/gate Tenant/Cell/deployment scope mismatch';foreach($table in @('markers','operations','effects','outbox')){foreach($record in (Rows $owner[$table])){Require ($record.fixture_id -eq $id -and $record.tenant_id -eq $scopeTenant) 'Cross-Tenant/cross-fixture owner row'}}
            foreach($effect in (Rows $owner.effects)){$operation=@($owner.operations | Where-Object {$_.tenant_id -eq $effect.tenant_id -and $_.operation_id -eq $effect.operation_id});Require ($operation.Count -eq 1 -and $operation[0].semantic_digest -eq $effect.semantic_digest) 'Effect not bound to durable operation semantic digest';$receipt=Wire $operation[0].receipt;Require ($receipt.category -eq $effect.category) 'Effect category differs from authenticated receipt';if($effect.category -eq 'HISTORICAL'){Require ($effect.operation_id -in $(if($effect.tenant_id -eq $tenant){@('op-historical-1','op-historical-2')}else{@('op-witness-1')})) 'Unapproved historical fixture effect'}else{$audit=@($owner.audit | Where-Object {$_.category -eq 'OPERATION' -and $_.operation_id -eq $effect.operation_id -and $_.tenant_id -eq $effect.tenant_id});Require ($audit.Count -eq 1 -and $audit[0].state -eq 'NEW' -and $audit[0].semantic_digest -eq $effect.semantic_digest) 'New effect lacks one atomic audit record'}}
            foreach($audit in (Rows $owner.audit)){Require ($audit.fixture_id -eq $id -and $audit.tenant_id -eq $scopeTenant -and $audit.category -in @('OPERATION','RECONSTRUCTION','RECOVERY')) 'Audit scope/category invalid'}
            foreach($record in (Rows $before.owners[$cell].effects)){Require ($record.category -eq 'HISTORICAL') 'Before snapshot already contained a new effect'};Require (@(Rows $owner.markers).Count -eq [int]$owner.schemaPresent) 'Marker count/schema mismatch';foreach($marker in (Rows $owner.markers)){$ordered=@(Rows $owner.operations | Sort-Object {[long]$_.sequence});Require ($marker.marker_id -eq 'marker' -and [long]$marker.version -eq $ordered.Count) 'Actual marker version/result prefix mismatch';for($i=0;$i -lt $ordered.Count;$i++){Require ([long]$ordered[$i].sequence -eq $i+1) 'Owner operation sequence gap'};if($ordered.Count){$last=Wire $ordered[-1].receipt;Require ($marker.value -ceq $last.value) 'Marker value differs from committed authenticated result'}else{Require ($marker.value -ceq 'INITIAL') 'Unoperated marker mutated'}}
            $reconstruction+=@(Rows $owner.audit | Where-Object category -eq 'RECONSTRUCTION');foreach($operation in (Rows $owner.operations)){
                $completion=@(Rows $after.authorities.recovery.completions | Where-Object {$_.tenant_id -eq $operation.tenant_id -and $_.operation_id -eq $operation.operation_id});$outbox=@(Rows $owner.outbox | Where-Object {$_.tenant_id -eq $operation.tenant_id -and $_.operation_id -eq $operation.operation_id});Require ($completion.Count -eq 1 -and $outbox.Count -eq 1 -and $completion[0].owner_receipt -eq $operation.receipt -and $outbox[0].receipt -eq $operation.receipt -and $outbox[0].acknowledged -and $completion[0].semantic_digest -eq $operation.semantic_digest) 'Operation/outbox/completion conflict'
