            $boundaries=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$archiveLength=$null;foreach($line in Get-Content "$e/backup-$id.jsonl"){$transfer=$line | ConvertFrom-Json -AsHashtable;Require ($transfer.fixture -eq $id -and $transfer.run -eq $result.run) 'Restore negative backup scope invalid';foreach($key in @($transfer.Keys | Where-Object {$_ -like 'boundary-*'})){$fact=Wire $transfer[$key];Require ($fact.sha256 -eq $gate.data_digest -and [long]$fact.bytes -gt 0) 'Restore negative backup hash mismatch';if($null -eq $archiveLength){$archiveLength=[long]$fact.bytes};Require ([long]$fact.bytes -eq $archiveLength) 'Restore negative archive length mismatch';[void]$boundaries.Add($fact.boundary)}};foreach($boundary in @('A-original','B-exported','C-sealed','C-transfer-sealed','D-imported','E-before-restore')){Require ($boundaries.Contains($boundary)) 'Restore negative missing archive integrity boundary'}
